from gymnasium import RewardWrapper


class DoubleReward(RewardWrapper):
    """
    Multiply every reward by a factor.
    """

    def __init__(self, env, factor=2.0):
        super().__init__(env)
        self._factor = factor

    def reward(self, reward):
        return reward * self._factor

